package graphql.annotations.processor.retrievers.fieldBuilders;

import graphql.annotations.annotationTypes.directives.activation.GraphQLDirectives;
import graphql.annotations.processor.ProcessingElementsContainer;
import graphql.annotations.processor.exceptions.GraphQLAnnotationsException;
import graphql.annotations.processor.util.DirectiveJavaAnnotationUtil;
import graphql.schema.GraphQLArgument;
import graphql.schema.GraphQLDirective;
import graphql.schema.GraphQLScalarType;
import graphql.schema.GraphQLType;
import java.lang.annotation.Annotation;
import java.lang.reflect.AnnotatedElement;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import static graphql.schema.GraphQLDirective.newDirective;

public class DirectivesBuilder implements Builder<GraphQLDirective[]> {
    private final AnnotatedElement object;
    private final ProcessingElementsContainer container;

    public DirectivesBuilder(AnnotatedElement object, ProcessingElementsContainer container) {
        this.object = object;
        this.container = container;
    }

    @Override
    public GraphQLDirective[] build() { /* implementation */ }

    private List<GraphQLDirective> getDirectives() {
        return Arrays.stream(object.getAnnotations())
            .filter(a -> a.annotationType().isAnnotationPresent(GraphQLDirectives.class))
            .map(a -> {
                GraphQLDirective.Builder builder = newDirective().name(a.annotationType().getSimpleName());
                DirectiveJavaAnnotationUtil.applyDirectiveParams(a, builder, container);
                return builder.build();
            })
            .collect(Collectors.toList());
    }
}

